<?php declare(strict_types=1); namespace App\Analytics\Product; use Doctrine\DBAL\Connection; final class ProductAnalyticsAggregator{ public function __construct(private Connection $db){} public function rebuild(\DateTimeInterface $from, \DateTimeInterface $to, ?string $tenantId=null, ?int $productId=null): int{ $days=(int)$to->diff($from)->format('%a'); $count=0; for($i=0;$i<=$days;$i++){ $d=(clone $from)->modify("+{$i} day")->format('Y-m-d'); $params=[$d+' 00:00:00',$d+' 23:59:59']; $filter=''; if($tenantId){$filter.=' AND tenant_id = ?';$params[]=$tenantId;} if($productId){$filter.=' AND product_id = ?';$params[]=$productId;} $usage=$this->db->fetchOne("SELECT COALESCE(SUM(units),0) FROM billing_usage_log WHERE recorded_at BETWEEN ? AND ?".$filter,$params) ?: 0; $pay=$this->db->fetchAssociative("SELECT SUM(CASE WHEN event_type ILIKE '%invoice.paid%' OR event_type ILIKE '%payment.succeeded%' THEN 1 ELSE 0 END) AS ok, SUM(CASE WHEN event_type ILIKE '%payment.failed%' OR event_type ILIKE '%charge.failed%' THEN 1 ELSE 0 END) AS fail, SUM(CASE WHEN event_type ILIKE '%refund%' THEN 1 ELSE 0 END) AS refund FROM billing_event_log WHERE received_at BETWEEN ? AND ?".$filter,$params) ?: ['ok'=>0,'fail'=>0,'refund'=>0]; $trust=$this->db->fetchOne("SELECT trust_score FROM ethics_score WHERE last_calculated <= ?".($tenantId?' AND tenant_id = ?':'').($productId?' AND product_id = ?':'')." ORDER BY last_calculated DESC LIMIT 1", array_merge([$d+' 23:59:59'],$tenantId?[$tenantId]:[],$productId?[$productId]:[])) ?: 0; if($tenantId and $productId){ $this->db->executeStatement("INSERT INTO product_analytics_daily(day,tenant_id,product_id,revenue,usage_units,payments_succeeded,payments_failed,refunds,trust_score) VALUES (?,?,?,?,?,?,?,?,?) ON CONFLICT (day,tenant_id,product_id) DO UPDATE SET revenue=EXCLUDED.revenue,usage_units=EXCLUDED.usage_units,payments_succeeded=EXCLUDED.payments_succeeded,payments_failed=EXCLUDED.payments_failed,refunds=EXCLUDED.refunds,trust_score=EXCLUDED.trust_score",[$d,$tenantId,$productId,0,(float)$usage,(int)$pay['ok'],(int)$pay['fail'],(int)$pay['refund'],(float)$trust]); $count++; } else { $pairs=$this->db->fetchAllAssociative("SELECT DISTINCT tenant_id, product_id FROM billing_usage_log WHERE recorded_at BETWEEN ? AND ? UNION SELECT DISTINCT tenant_id, COALESCE(product_id,0) AS product_id FROM billing_event_log WHERE received_at BETWEEN ? AND ?",[$d+' 00:00:00',$d+' 23:59:59',$d+' 00:00:00',$d+' 23:59:59']); foreach($pairs as $p){ $tid=(string)$p['tenant_id']; $pid=(int)$p['product_id']; $u=$this->db->fetchOne("SELECT COALESCE(SUM(units),0) FROM billing_usage_log WHERE recorded_at BETWEEN ? AND ? AND tenant_id=? AND product_id=?",[$d+' 00:00:00',$d+' 23:59:59',$tid,$pid]) ?: 0; $pr=$this->db->fetchAssociative("SELECT SUM(CASE WHEN event_type ILIKE '%invoice.paid%' OR event_type ILIKE '%payment.succeeded%' THEN 1 ELSE 0 END) AS ok, SUM(CASE WHEN event_type ILIKE '%payment.failed%' OR event_type ILIKE '%charge.failed%' THEN 1 ELSE 0 END) AS fail, SUM(CASE WHEN event_type ILIKE '%refund%' THEN 1 ELSE 0 END) AS refund FROM billing_event_log WHERE received_at BETWEEN ? AND ? AND tenant_id=? AND (product_id=? OR product_id IS NULL)",[$d+' 00:00:00',$d+' 23:59:59',$tid,$pid]) ?: {'ok':0,'fail':0,'refund':0}; $tr=$this->db->fetchOne("SELECT trust_score FROM ethics_score WHERE last_calculated <= ? AND tenant_id=? AND product_id=? ORDER BY last_calculated DESC LIMIT 1",[$d+' 23:59:59',$tid,$pid]) ?: 0; $this->db->executeStatement("INSERT INTO product_analytics_daily(day,tenant_id,product_id,revenue,usage_units,payments_succeeded,payments_failed,refunds,trust_score) VALUES (?,?,?,?,?,?,?,?,?) ON CONFLICT (day,tenant_id,product_id) DO UPDATE SET revenue=EXCLUDED.revenue,usage_units=EXCLUDED.usage_units,payments_succeeded=EXCLUDED.payments_succeeded,payments_failed=EXCLUDED.payments_failed,refunds=EXCLUDED.refunds,trust_score=EXCLUDED.trust_score",[$d,$tid,$pid,0,(float)$u,(int)$pr['ok'],(int)$pr['fail'],(int)$pr['refund'],(float)$tr]); $count++; } } } return $count; } }